const now = new Date().toISOString();
const suffix = Math.random().toString(36).slice(2, 7).toUpperCase();
const requestId = `APR-BUTTON-TEST-${Date.now()}-${suffix}`;

const testRecord = {
  request_id: requestId,
  customer_id: 'CUST-TEST-1001',
  telegram_chat_id: `TEST-CHAT-${suffix}`,
  session_id: `TEST-SESSION-${suffix}`,
  request_type: 'refund_exception',
  reason: 'Customer requested a refund exception outside the standard policy window.',
  ai_recommendation: 'Escalate to a human reviewer.',
  status: 'PENDING',
  created_at: now,
  reviewer_id: '',
  reviewer_name: '',
  decision: '',
  decision_comment: '',
  decided_at: '',
  test_record: 'true'
};

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: 'HUMAN APPROVAL — END-TO-END TEST', emoji: true }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text:
        `*Request ID:* ${requestId}\n` +
        `*Customer:* ${testRecord.customer_id}\n` +
        `*Request type:* ${testRecord.request_type}\n` +
        `*Reason:* ${testRecord.reason}\n` +
        `*AI recommendation:* ${testRecord.ai_recommendation}\n` +
        `*Status:* PENDING`
    }
  },
  {
    type: 'actions',
    block_id: `approval_test_${suffix}`,
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Approve (TEST)', emoji: true },
        style: 'primary',
        action_id: 'approval_approve_test',
        value: requestId,
        confirm: {
          title: { type: 'plain_text', text: 'Confirm test approval?' },
          text: { type: 'mrkdwn', text: 'This updates the test record in the development DynamoDB table only. No customer action will be performed.' },
          confirm: { type: 'plain_text', text: 'Approve test' },
          deny: { type: 'plain_text', text: 'Cancel' }
        }
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Reject (TEST)', emoji: true },
        style: 'danger',
        action_id: 'approval_reject_test',
        value: requestId,
        confirm: {
          title: { type: 'plain_text', text: 'Confirm test rejection?' },
          text: { type: 'mrkdwn', text: 'This updates the test record in the development DynamoDB table only. No customer action will be performed.' },
          confirm: { type: 'plain_text', text: 'Reject test' },
          deny: { type: 'plain_text', text: 'Cancel' }
        }
      }
    ]
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: `Test record created at ${now}. This is an end-to-end development test.` }
    ]
  }
];

return [{
  json: {
    request_id: requestId,
    fallback_text: `HITL end-to-end test for ${requestId}.`,
    blocks,
    test_record: testRecord
  }
}];

const items = $input.all();

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBody = buffer.toString('utf8');

return items.map(item => ({
  json: {
    ...item.json,
    rawBodyDiagnostic: {
      available: true,
      length: buffer.length,
      startsWithPayload: rawBody.startsWith('payload='),
      containsPayload: rawBody.includes('payload=')
    }
  },
  binary: item.binary
}));

const item = $input.first();

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBody = buffer.toString('utf8');

const headers = item.json.headers || {};
const timestamp = headers['x-slack-request-timestamp'];
const receivedSignature = headers['x-slack-signature'];

if (!timestamp || !receivedSignature) {
  throw new Error('Missing Slack signature headers');
}

const requestTime = Number(timestamp);
const currentTime = Math.floor(Date.now() / 1000);
const ageSeconds = currentTime - requestTime;

const timestampFresh = ageSeconds >= -60 && ageSeconds <= 300;

if (!timestampFresh) {
  throw new Error('Slack request timestamp is expired or invalid');
}

const signatureBase = `v0:${timestamp}:${rawBody}`;

return [{
  json: {
    signatureBase,
    receivedSignature,
    timestampFresh,
    ageSeconds,
    rawBodyLength: buffer.length
  },
  binary: item.binary
}];

const item = $input.first().json;

const expected = 'v0=' + String(item.calculatedSignature || '');
const received = String(item.receivedSignature || '');

function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let difference = 0;
  for (let i = 0; i < a.length; i++) {
    difference |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return difference === 0;
}

const signatureMatches =
  expected !== 'v0=' &&
  received.length > 0 &&
  safeEqual(expected, received);

const timestampFresh = item.timestampFresh === true;
const authorized = signatureMatches && timestampFresh;

return [{
  json: {
    authorized,
    signatureVerified: signatureMatches,
    timestampFresh,
    ageSeconds: item.ageSeconds,
    reason: authorized
      ? 'SIGNATURE_VERIFIED'
      : (!timestampFresh ? 'STALE_OR_INVALID_TIMESTAMP' : 'INVALID_SLACK_SIGNATURE')
  }
}];

const webhook = $('Webhook - Slack Interaction').first();
const webhookJson = webhook.json ?? {};
let payloadText =
  webhookJson.body?.payload ??
  webhookJson.payload ??
  webhookJson.body?.['payload'];

let payload = null;

// Slack sends application/x-www-form-urlencoded with a "payload" field.
// Depending on n8n webhook parsing, it may already be decoded in body.payload.
if (typeof payloadText === 'string' && payloadText.trim()) {
  try {
    payload = JSON.parse(payloadText);
  } catch (error) {
    throw new Error(`Slack payload field is not valid JSON: ${error.message}`);
  }
}

// Fallback: parse the original raw request body when the form field was not
// exposed as webhookJson.body.payload by the Webhook node.
if (!payload) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    const rawBody = buffer.toString('utf8');
    const marker = rawBody.match(/(?:^|&)payload=([^&]*)/);
    if (marker?.[1]) {
      payload = JSON.parse(decodeURIComponent(marker[1].replace(/\\+/g, ' ')));
    }
  } catch (error) {
    // The primary parsed-body path above remains authoritative when available.
  }
}

if (!payload || typeof payload !== 'object') {
  throw new Error('Could not extract Slack interaction payload from the request body.');
}
if (payload.type !== 'block_actions') {
  throw new Error(`Unsupported Slack interaction type: ${String(payload.type ?? 'missing')}`);
}
if (!payload.user?.id || !payload.channel?.id) {
  throw new Error('Slack interaction is missing reviewer or channel identifiers.');
}
if (!Array.isArray(payload.actions) || payload.actions.length !== 1) {
  throw new Error('Expected exactly one Slack button action.');
}

const action = payload.actions[0];
const decisions = {
  approval_approve_test: 'APPROVED',
  approval_reject_test: 'REJECTED',
  approve_support_request: 'APPROVED',
  reject_support_request: 'REJECTED'
};
const decision = decisions[action.action_id];
if (!decision) throw new Error(`Unsupported approval action: ${String(action.action_id ?? 'missing')}`);

const requestId = String(action.value ?? '').trim();
if (!requestId || requestId.length > 128) throw new Error('Invalid approval request ID.');

// CONFIGURATION: replace this with the real Slack channel ID for #support-approvals.
// Keep the stable channel-ID check; do not rely on channel name alone.
const APPROVAL_CHANNEL_ID = 'C0CGU4ALYBX';
if (payload.channel.id !== APPROVAL_CHANNEL_ID) {
  throw new Error(`Approval action received from an unauthorized channel (${payload.channel.id}).`);
}

return [{
  json: {
    request_id: requestId,
    decision,
    reviewer_id: String(payload.user.id),
    reviewer_name: String(payload.user.username || payload.user.name || payload.user.real_name || 'Unknown'),
    channel_id: String(payload.channel.id),
    channel_name: String(payload.channel.name || ''),
    action_id: String(action.action_id),
    decided_at: new Date().toISOString()
  }
}];

const item = $input.first().json;

// CONFIGURATION: replace with the Slack member IDs authorized to approve.
// Use Slack member IDs (U...), never display names or email addresses.
const ALLOWED_REVIEWER_IDS = ['U0CGT5U9N59'];
const reviewerId = String(item.reviewer_id ?? '');
const allowed = ALLOWED_REVIEWER_IDS.includes(reviewerId);

return [{
  json: {
    ...item,
    reviewerAuthorized: allowed,
    reason: allowed ? 'AUTHORIZED_REVIEWER' : 'REVIEWER_NOT_AUTHORIZED'
  }
}];

const item = $input.first().json;

if (item.reviewerAuthorized !== true) {
  throw new Error('Reviewer authorization failed');
}

return [{
  json: {
    request_id: item.request_id,
    decision: item.decision,
    status: item.decision,
    reviewer_id: item.reviewer_id,
    reviewer_name: item.reviewer_name,
    channel_id: item.channel_id,
    action_id: item.action_id,
    decided_at: item.decided_at,
    approval_update_ready: true
  }
}];

const response = $input.first().json;

const decision = $('Code - Build Authorized Decision Record').first().json;

// STEP 1: Extract the HTTP response.
let payload = response.data ?? response.body ?? response;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (error) {
    throw new Error(
      `DynamoDB response is not valid JSON: ${error.message}`
    );
  }
}

// STEP 2: Extract the DynamoDB Item.
const item = payload.Item;

if (!item) {
  throw new Error(
    `Approval record not found. DynamoDB response: ${JSON.stringify(payload)}`
  );
}

// STEP 3: Decode DynamoDB AttributeValue objects.
function decodeAttributeValue(value) {
  if (value === null || typeof value !== 'object') {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map(decodeAttributeValue);
  }

  if (Object.prototype.hasOwnProperty.call(value, 'S')) {
    return value.S;
  }

  if (Object.prototype.hasOwnProperty.call(value, 'N')) {
    return Number(value.N);
  }

  if (Object.prototype.hasOwnProperty.call(value, 'BOOL')) {
    return value.BOOL;
  }

  if (Object.prototype.hasOwnProperty.call(value, 'NULL')) {
    return null;
  }

  if (Object.prototype.hasOwnProperty.call(value, 'SS')) {
    return value.SS;
  }

  if (Object.prototype.hasOwnProperty.call(value, 'NS')) {
    return value.NS.map(Number);
  }

  if (Object.prototype.hasOwnProperty.call(value, 'L')) {
    return value.L.map(decodeAttributeValue);
  }

  if (Object.prototype.hasOwnProperty.call(value, 'M')) {
    return decodeItem(value.M);
  }

  return decodeItem(value);
}

function decodeItem(attributes) {
  const result = {};

  for (const [key, value] of Object.entries(attributes)) {
    result[key] = decodeAttributeValue(value);
  }

  return result;
}

// STEP 4: Convert DynamoDB record to ordinary JSON.
const record = decodeItem(item);

// STEP 5: Validate request ID.
if (!record.request_id) {
  throw new Error('DynamoDB record has no request_id');
}

if (String(record.request_id) !== String(decision.request_id)) {
  throw new Error(
    `Request ID mismatch. Database: ${record.request_id}, Decision: ${decision.request_id}`
  );
}

// STEP 6: Validate current status.
if (record.status !== 'PENDING') {
  throw new Error(
    `Approval already processed. Current status: ${record.status}`
  );
}

// STEP 7: Validate requested decision.
const requestedDecision = String(decision.decision || '').toUpperCase();

if (!['APPROVED', 'REJECTED'].includes(requestedDecision)) {
  throw new Error('Invalid approval decision');
}

// STEP 8: Identify test versus production approval.
const isTestRecord =
  record.test_record === true ||
  String(record.test_record ?? '').toLowerCase() === 'true';

const resumeUrl = String(record.resume_url ?? '').trim();

// Production approvals must have a resume URL.
// Test records are allowed to use the existing test-only path.
if (!isTestRecord && !resumeUrl) {
  throw new Error(
    'Production approval is missing resume_url. Cannot safely resume Supervisor execution.'
  );
}

// STEP 9: Merge existing record with new decision.
const updated = {
  ...record,

  status: requestedDecision,
  decision: requestedDecision,

  reviewer_id: decision.reviewer_id,
  reviewer_name: decision.reviewer_name,
  decided_at: decision.decided_at,

  decision_comment: record.decision_comment || '',

  // HITL execution correlation.
  resume_url: resumeUrl,
  test_record: isTestRecord ? 'true' : 'false',
  resume_required: !isTestRecord,
  resume_ready: isTestRecord || Boolean(resumeUrl),

  approval_update_ready: true,

  // Debug information.
  debug: {
    source: 'DynamoDB HTTP GetItem',
    record_found: true,
    request_id_matched: true,
    previous_status: record.status,
    new_status: requestedDecision,
    test_record: isTestRecord,
    resume_url_available: Boolean(resumeUrl),
    resume_required: !isTestRecord,
    validation_passed: true
  }
};

// STEP 10: Return the complete record.
return [{ json: updated }];

