const record = $('Code - Merge Existing Record and Decision').first().json;
return [{json:{
  correlation_id: record.correlation_id || `APR-${record.request_id}`,
  execution_id: String($execution.id),
  workflow_name: "WF_Slack_Interactive_Approval_HTTP_DynamoDB_E2E",
  event_name: "approval_decision_recorded",
  status: record.status,
  intent: record.request_type || "approval_required",
  target_agent: "approval_required",
  logged_at: record.decided_at || new Date().toISOString()
}}];
